import{_ as a,o as r,c as s,ag as o}from"./chunks/framework.DXGyWiRo.js";const e="/assets/pc1.DKuszYvI.png",n="/assets/pc2.Mhi9Kc5t.png",i="/assets/pc3.Bn_2Ju5H.png",p="/assets/pc4.Dqy9_Zy2.png",l="/assets/pc5.BKVRoFea.png",h="/assets/pc6.fyAPjQBF.png",c="/assets/pc7.CzVDGh-w.png",d="/assets/pc8.CyiparCx.png",x=JSON.parse('{"title":"🌐 Hiddify 基础使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"vpn/pc.md","filePath":"vpn/pc.md"}'),g={name:"vpn/pc.md"};function _(m,t,u,b,f,q){return r(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="🌐-hiddify-基础使用教程" tabindex="-1">🌐 Hiddify 基础使用教程 <a class="header-anchor" href="#🌐-hiddify-基础使用教程" aria-label="Permalink to &quot;🌐 Hiddify 基础使用教程&quot;">​</a></h1><h3 id="_1-获取应用" tabindex="-1">1. 获取应用 <a class="header-anchor" href="#_1-获取应用" aria-label="Permalink to &quot;1. 获取应用&quot;">​</a></h3><ul><li><strong>Hiddify 官方 Github 下载地址</strong>：<a href="https://github.com/hiddify/hiddify-next/blob/main/README_cn.md" target="_blank" rel="noreferrer">点击前往下载 (需科学上网)</a></li></ul><blockquote><p>你也可以选择其他应用，这里主要讲Hiddfy的使用方法，别的软件也差不多一样，导入链接&gt;系统代理&gt;应用全局</p></blockquote><ul><li><strong>Clash 官方 Github 下载地址</strong>：<a href="https://github.com/clashbk/clash" target="_blank" rel="noreferrer">点击前往下载 (需科学上网)</a></li></ul><hr><h3 id="_2-安装流程" tabindex="-1">2. 安装流程 <a class="header-anchor" href="#_2-安装流程" aria-label="Permalink to &quot;2. 安装流程&quot;">​</a></h3><p>下载安装包后打开，按下图勾选，然后点击 <strong>Next</strong></p><p><img src="'+e+'" alt="勾选组件"></p><p>接着点击 <strong>Install</strong> 进行安装</p><p><img src="'+n+'" alt="点击安装"></p><p>最后点击 <strong>Finish</strong> 完成安装并启动</p><p><img src="'+i+'" alt="完成安装"></p><hr><h3 id="_3-基础设置与导入订阅" tabindex="-1">3. 基础设置与导入订阅 <a class="header-anchor" href="#_3-基础设置与导入订阅" aria-label="Permalink to &quot;3. 基础设置与导入订阅&quot;">​</a></h3><h4 id="第一步-初始化设置" tabindex="-1">第一步：初始化设置 <a class="header-anchor" href="#第一步-初始化设置" aria-label="Permalink to &quot;第一步：初始化设置&quot;">​</a></h4><p>进入软件后，语言可以选择 <strong>中文</strong>。 地区选择 <strong>中国</strong> 或其他，然后点击 <strong>开始</strong></p><p><img src="'+p+'" alt="初始化设置"></p><h4 id="第二步-获取并复制订阅" tabindex="-1">第二步：获取并复制订阅 <a class="header-anchor" href="#第二步-获取并复制订阅" aria-label="Permalink to &quot;第二步：获取并复制订阅&quot;">​</a></h4><p>去联系 <strong>卢老爷</strong> 获取你的专用订阅链接，并将其 <strong>复制</strong> 到剪贴板</p><h4 id="第三步-导入配置文件" tabindex="-1">第三步：导入配置文件 <a class="header-anchor" href="#第三步-导入配置文件" aria-label="Permalink to &quot;第三步：导入配置文件&quot;">​</a></h4><p>回到软件主界面，点击下方的 <strong>“新的配置文件”</strong></p><p><img src="'+l+'" alt="点击新配置文件"></p><p>在弹出的选项中，选择 <strong>“从剪贴板导入”</strong></p><p><img src="'+h+'" alt="从剪贴板导入"></p><h4 id="第四步-开启科学上网" tabindex="-1">第四步：开启科学上网 <a class="header-anchor" href="#第四步-开启科学上网" aria-label="Permalink to &quot;第四步：开启科学上网&quot;">​</a></h4><p>导入成功后，点击中间的大圆圈按钮 <strong>“点击连接”</strong></p><p><img src="'+c+'" alt="点击连接"></p><p>此时已经科学上网成功！你可以在 <strong>代理</strong> 选项卡中自由选择你想要的节点</p><p><img src="'+d+'" alt="节点选择"></p><hr><h3 id="💡-lbw-sir-提示" tabindex="-1">💡 LBW SIR 提示 <a class="header-anchor" href="#💡-lbw-sir-提示" aria-label="Permalink to &quot;💡 LBW SIR 提示&quot;">​</a></h3><ul><li><strong>连接失败？</strong> 请检查你的 VPN/加速器是否已开启全局模式，或者尝试更换节点。</li></ul>',33)])])}const P=a(g,[["render",_]]);export{x as __pageData,P as default};
